import csv
import json
from pathlib import Path

status = {'A': 'active', 'C': 'closed', 'P': 'pending'}
with open('/app/data/active.csv', newline='') as source:
    records = [
        {'id': row['id'], 'name': f"{row['first_name']} {row['last_name']}", 'status': status[row['status']]}
        for row in csv.DictReader(source)
    ]
Path('/app/out/migrated.json').write_text(json.dumps(records, indent=2) + '\n')
